# Just like in interviews, please do not use python libraries to take shortcuts.
# They aren't usually allowed in real interviews.
# Add comments to each step of your logic

def finishTime(n, edges, baseTime):
    # A single task is a leaf
    if n == 1:
        return baseTime[0]

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from node 0: parent array and top-down order
    parent = [-1] * n
    order = [0]
    for u in order:
        for w in adj[u]:
            if w != parent[u]:
                parent[w] = u
                order.append(w)

    # down[u] = finish time of u using only its subtree (rooted at 0)
    down = [0] * n
    for u in reversed(order):
        hi = lo = None
        for w in adj[u]:
            if w != parent[u]:
                x = down[w]
                if hi is None or x > hi:
                    hi = x
                if lo is None or x < lo:
                    lo = x
        # leaf: no children; otherwise latest + (latest - earliest) + base
        down[u] = baseTime[u] if hi is None else 2 * hi - lo + baseTime[u]

    # up[c] = finish time of parent[c] when the tree is viewed from c
    up = [0] * n
    best = None
    for u in order:
        # values of all neighbours of u: children use down[], the parent side uses up[u]
        vals = []
        for w in adj[u]:
            vals.append((up[u] if w == parent[u] else down[w], w))

        # two largest and two smallest values, each tagged with the neighbour that owns it
        mx1 = mx2 = None
        mn1 = mn2 = None
        for x, w in vals:
            if mx1 is None or x > mx1[0]:
                mx2 = mx1
                mx1 = (x, w)
            elif mx2 is None or x > mx2[0]:
                mx2 = (x, w)
            if mn1 is None or x < mn1[0]:
                mn2 = mn1
                mn1 = (x, w)
            elif mn2 is None or x < mn2[0]:
                mn2 = (x, w)

        # finish time of u if u itself is the root
        total = 2 * mx1[0] - mn1[0] + baseTime[u]
        if best is None or total < best:
            best = total

        # for each child c, compute up[c]: u's finish time with c removed from its neighbours
        for w in adj[u]:
            if w == parent[u]:
                continue
            if len(vals) == 1:
                up[w] = baseTime[u]              # u has no other neighbour, so it is a leaf
            else:
                hi = mx2[0] if mx1[1] == w else mx1[0]
                lo = mn2[0] if mn1[1] == w else mn1[0]
                up[w] = 2 * hi - lo + baseTime[u]
    return best
